<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?><header class="sd-site-header <?php echo sd_get_option( 'sd_sticky_header' ) ? 'is-sticky' : ''; ?>"><div class="sd-container sd-header-inner"><?php sd_render_site_branding(); ?><nav class="sd-main-nav" aria-label="<?php esc_attr_e( 'Primary menu', 'social-discovery' ); ?>"><?php sd_menu( 'primary' ); ?></nav><div class="sd-header-actions"><?php if ( sd_get_option( 'sd_header_search' ) ) : ?><a class="sd-icon-button" href="<?php echo esc_url( home_url( '/?s=' ) ); ?>" aria-label="<?php esc_attr_e( 'Search', 'social-discovery' ); ?>">⌕</a><?php endif; ?><button class="sd-icon-button sd-mode-toggle" type="button" data-sd-mode-toggle aria-pressed="false" aria-label="<?php esc_attr_e( 'Toggle color mode', 'social-discovery' ); ?>">◐</button><?php if ( is_user_logged_in() ) : ?><a class="sd-header-account" href="<?php echo esc_url( sd_auth_profile_url() ); ?>"><img src="<?php echo esc_url( sd_avatar( get_current_user_id(), 40 ) ); ?>" alt="" width="32" height="32"><span class="screen-reader-text"><?php esc_html_e( 'My profile', 'social-discovery' ); ?></span></a><a class="sd-icon-button" href="<?php echo esc_url( sd_auth_account_url() ); ?>" aria-label="<?php esc_attr_e( 'Account settings', 'social-discovery' ); ?>">⚙</a><a class="sd-icon-button" href="<?php echo esc_url( sd_auth_logout_url() ); ?>" aria-label="<?php esc_attr_e( 'Log out', 'social-discovery' ); ?>">↪</a><?php elseif ( sd_get_option( 'sd_header_auth' ) ) : ?><a class="sd-button sd-button-outline" href="<?php echo esc_url( sd_auth_url( 'login', wp_login_url() ) ); ?>"><?php esc_html_e( 'Log in', 'social-discovery' ); ?></a><?php if ( get_option( 'users_can_register' ) ) : ?><a class="sd-button sd-button-primary" href="<?php echo esc_url( sd_auth_url( 'register', wp_registration_url() ) ); ?>"><?php esc_html_e( 'Join free', 'social-discovery' ); ?></a><?php endif; ?><?php endif; ?><?php if ( sd_get_option( 'sd_header_cta_enabled' ) && sd_get_option( 'sd_header_cta_url' ) ) : ?><a class="sd-button sd-button-primary" href="<?php echo esc_url( sd_get_option( 'sd_header_cta_url' ) ); ?>"><?php echo esc_html( sd_get_option( 'sd_header_cta_text' ) ); ?></a><?php endif; ?><button class="sd-menu-toggle" type="button" aria-expanded="false" aria-controls="sd-mobile-drawer" aria-label="<?php esc_attr_e( 'Open menu', 'social-discovery' ); ?>">☰</button></div></div><?php get_template_part( 'template-parts/header/mobile-menu' ); ?></header>
